import zipfile
from xml.etree import ElementTree as ET

M = "http://schemas.openxmlformats.org/spreadsheetml/2006/main"
R = "http://schemas.openxmlformats.org/officeDocument/2006/relationships"

def cell_text(c, shared):
    t = c.get("t")
    if t == "s":
        v = c.find("{%s}v" % M)
        return shared[int(v.text)] if v is not None and v.text is not None else ""
    if t == "inlineStr":
        return "".join(x.text or "" for x in c.iter("{%s}t" % M))
    v = c.find("{%s}v" % M)
    return v.text if v is not None else ""

def to_num(s):
    s = (s or "").strip().replace(",", "").replace("$", "").replace(" ", "")
    if not s:
        return None
    try:
        return float(s)
    except ValueError:
        return None

with zipfile.ZipFile("budget.xlsx") as z:
    wb = ET.fromstring(z.read("xl/workbook.xml"))
    rels = ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))
    rel_map = {r.get("Id"): r.get("Target") for r in rels}
    sheets = [(s.get("name"), s.get("{%s}id" % R)) for s in wb.find("{%s}sheets" % M)]
    shared = []
    if "xl/sharedStrings.xml" in z.namelist():
        ss = ET.fromstring(z.read("xl/sharedStrings.xml"))
        for si in ss.findall("{%s}si" % M):
            shared.append("".join(t.text or "" for t in si.iter("{%s}t" % M)))
    grand = 0.0
    for name, rid in sheets:
        target = rel_map[rid]
        if target.startswith("/"):
            target = target.lstrip("/")
        elif not target.startswith("xl/"):
            target = "xl/" + target
        root = ET.fromstring(z.read(target))
        print(f"--- Sheet: {name} ---")
        sheet_nums = []
        for row in root.iter("{%s}row" % M):
            items = []
            nums = []
            for c in row.findall("{%s}c" % M):
                text = cell_text(c, shared)
                items.append(f"{c.get('r')}={text!r}")
                n = to_num(text)
                if n is not None:
                    nums.append(n)
            sheet_nums.extend(nums)
            print(" | ".join(items) + f"   [row numeric sum: {sum(nums)}]")
        st = sum(sheet_nums)
        grand += st
        print(f"[sheet numeric total: {st}]")
    print(f"\nGRAND TOTAL (sum of all numeric cells, incl. any 'Total' rows): {grand}")

